80:parameter	[NS*AW-1:0]	SLAVE_ADDR = {
81:{ 3'b111, {(AW-3){1'b0}} },
82:{ 3'b110, {(AW-3){1'b0}} },
83:{ 3'b101, {(AW-3){1'b0}} },
