149:output	wire	[NS*AW-1:0]	o_saddr,
150:output	wire	[NS*DW-1:0]	o_sdata,
151:output	wire	[NS*DW/8-1:0]	o_ssel,
154:input	wire	[NS-1:0]	i_sstall, i_sack,
155:input	wire	[NS*DW-1:0]	i_sdata,
156:input	wire	[NS-1:0]	i_serr
158:);
168:localparam	TIMEOUT_WIDTH = $clog2(OPT_TIMEOUT);
172:localparam	LGNM = (NM>1) ? $clog2(NM) : 1;
179:localparam	LGNS = $clog2(NS+1);
